// Writes src/index.ts: friendly aliases for every schema in openapi.json. GENERATED — do not edit by hand.
import { readFileSync, writeFileSync } from "node:fs";

const spec = JSON.parse(readFileSync(new URL("../openapi.json", import.meta.url)));
const names = Object.keys(spec.components.schemas).sort();
const lines = [
  "// GENERATED by packages/contracts/scripts/write-index.mjs from openapi.json. Do not edit.",
  "// Source of truth: apps/api/app/contracts (Pydantic v2). Regenerate: scripts/generate-contracts.sh",
  'import type { components, paths, operations } from "./generated/openapi";',
  "export type { components, paths, operations };",
  "type S = components[\"schemas\"];",
  `export const SCHEMA_VERSION = ${JSON.stringify(spec.info["x-schema-version"])};`,
  // Models used as both request and response are split by FastAPI into "X-Input" / "X-Output".
  // Alias X -> response shape (all always-present fields required); XInput -> request shape.
  ...names.flatMap((n) => {
    if (n.endsWith("-Output")) return [`export type ${n.slice(0, -7)} = S[${JSON.stringify(n)}];`];
    if (n.endsWith("-Input")) return [`export type ${n.slice(0, -6)}Input = S[${JSON.stringify(n)}];`];
    if (names.includes(`${n}-Output`)) return []; // registry copy superseded by the route's response schema
    return /^[A-Za-z_][A-Za-z0-9_]*$/.test(n) ? [`export type ${n} = S[${JSON.stringify(n)}];`] : [];
  }),
  "",
];
writeFileSync(new URL("../src/index.ts", import.meta.url), lines.join("\n"));
console.log(`wrote ${names.length} schema aliases`);
